# Apartats 1.9-1.10 (potències amb base entera i racional, i propietats de les potències) dels apunts de la Unitat 1 de 4t ESO A.
# Part de la teoria ve de ../2eso-t1/build.py (1.10) i ../2eso-t2/pot.py (2.9). Les asserts comproven els resultats escrits a mà.
from eines4a import *

def chk(e, v): assert ev(e) == v, (e, ev(e), v)
def pw(a, b, n): return Fr(a, b) ** n

# ============================================================ 1.9 Potències amb base entera i racional
s9 = box('def', L('Potències amb base entera', 'Potencias con base entera', 'Powers with an integer base'),
  P(r"Una potència \(a^n\) (amb \(n\) natural) és el producte de \(n\) factors iguals a la base \(a\). Si la base és un enter <strong>negatiu</strong>, l'escrivim entre parèntesis i el signe del resultat depén de l'exponent:",
    r"Una potencia \(a^n\) (con \(n\) natural) es el producto de \(n\) factores iguales a la base \(a\). Si la base es un entero <strong>negativo</strong>, la escribimos entre paréntesis y el signo del resultado depende del exponente:",
    r"A power \(a^n\) (with \(n\) a natural number) is the product of \(n\) factors equal to the base \(a\). If the base is a <strong>negative</strong> integer, we write it in brackets and the sign of the result depends on the exponent:")
  + table([L('Base', 'Base', 'Base'), L('Exponent', 'Exponente', 'Exponent'), L('Signe', 'Signo', 'Sign'), L('Exemple', 'Ejemplo', 'Example')],
          [[L('positiva', 'positiva', 'positive'), L('qualsevol', 'cualquiera', 'any'), '<span class="pos">+</span>', r'\(2^5=32\)'],
           [L('negativa', 'negativa', 'negative'), L('parell', 'par', 'even'), '<span class="pos">+</span>', r'\((-2)^4=(-2)\cdot(-2)\cdot(-2)\cdot(-2)=16\)'],
           [L('negativa', 'negativa', 'negative'), L('senar', 'impar', 'odd'), '<span class="neg">−</span>', r'\((-2)^3=(-2)\cdot(-2)\cdot(-2)=-8\)']])
  + box('warn', L('Compte amb el parèntesi', 'Cuidado con el paréntesis', 'Watch the brackets'),
        r'\[(-3)^2=(-3)\cdot(-3)=9\qquad\qquad -3^2=-(3\cdot3)=-9\]'
        + P(r"Sense parèntesi, la base és \(3\) i el signe \(-\) queda fora de la potència. Recorda també que \(a^1=a\) i \(a^0=1\) (si \(a\neq0\)): \((-7)^1=-7\), \((-7)^0=1\).", r"Sin paréntesis, la base es \(3\) y el signo \(-\) queda fuera de la potencia. Recuerda también que \(a^1=a\) y \(a^0=1\) (si \(a\neq0\)): \((-7)^1=-7\), \((-7)^0=1\).", r"Without brackets the base is \(3\) and the minus sign stays outside the power. Remember also that \(a^1=a\) and \(a^0=1\) (if \(a\neq0\)): \((-7)^1=-7\), \((-7)^0=1\).")))
chk('(-2)^4', 16); chk('(-2)^3', -8); chk('(-3)^2', 9); chk('-3^2', -9)
s9 += W_powz + drillz('pow', 'Entrena: potències i arrels amb enters', 'Entrena: potencias y raíces con enteros', 'Train: powers and roots with integers')
s9 += box('def', L('Potències amb base racional (una fracció)', 'Potencias con base racional (una fracción)', 'Powers with a rational base (a fraction)'),
  P(r"Per a elevar una fracció a un nombre natural \(n\), elevem el <strong>numerador</strong> i el <strong>denominador</strong>:",
    r"Para elevar una fracción a un número natural \(n\), elevamos el <strong>numerador</strong> y el <strong>denominador</strong>:",
    r"To raise a fraction to a natural number \(n\), raise the <strong>numerator</strong> and the <strong>denominator</strong>:")
  + r'\[\left(\frac{a}{b}\right)^n=\frac{a^n}{b^n}\qquad\left(\frac{2}{3}\right)^4=\frac{2}{3}\cdot\frac{2}{3}\cdot\frac{2}{3}\cdot\frac{2}{3}=\frac{2^4}{3^4}=\frac{16}{81}\]'
  + ul(L(r"El <strong>signe</strong> funciona com amb els enters: \(\left(-\frac{1}{2}\right)^4=\frac{1}{16}\) (exponent parell), \(\ \left(-\frac{1}{2}\right)^3=-\frac{1}{8}\) (exponent senar).", r"El <strong>signo</strong> funciona como con los enteros: \(\left(-\frac{1}{2}\right)^4=\frac{1}{16}\) (exponente par), \(\ \left(-\frac{1}{2}\right)^3=-\frac{1}{8}\) (exponente impar).", r"The <strong>sign</strong> works as with integers: \(\left(-\frac{1}{2}\right)^4=\frac{1}{16}\) (even exponent), \(\ \left(-\frac{1}{2}\right)^3=-\frac{1}{8}\) (odd exponent)."),
         L(r"\(\left(\frac{a}{b}\right)^1=\frac{a}{b}\) &nbsp; i &nbsp; \(\left(\frac{a}{b}\right)^0=1\).", r"\(\left(\frac{a}{b}\right)^1=\frac{a}{b}\) &nbsp; y &nbsp; \(\left(\frac{a}{b}\right)^0=1\).", r"\(\left(\frac{a}{b}\right)^1=\frac{a}{b}\) &nbsp; and &nbsp; \(\left(\frac{a}{b}\right)^0=1\)."),
         L(r"Compte amb els parèntesis: \(\ \left(\frac{2}{3}\right)^2=\frac{4}{9}\), però \(\ \frac{2^2}{3}=\frac{4}{3}\) i \(\ -\left(\frac{2}{3}\right)^2=-\frac{4}{9}\).", r"Cuidado con los paréntesis: \(\ \left(\frac{2}{3}\right)^2=\frac{4}{9}\), pero \(\ \frac{2^2}{3}=\frac{4}{3}\) y \(\ -\left(\frac{2}{3}\right)^2=-\frac{4}{9}\).", r"Watch the brackets: \(\ \left(\frac{2}{3}\right)^2=\frac{4}{9}\), but \(\ \frac{2^2}{3}=\frac{4}{3}\) and \(\ -\left(\frac{2}{3}\right)^2=-\frac{4}{9}\).")))
ck(pw(2, 3, 4), Fr(16, 81)); ck(pw(-1, 2, 4), Fr(1, 16)); ck(pw(-1, 2, 3), Fr(-1, 8))
s9 += widget('w-pow', '⚡', L('Potències de fraccions', 'Potencias de fracciones', 'Powers of fractions'),
  f'  <div class="wrow">{gseg("m", [("p", L("Potència", "Potencia", "Power")), ("m", L("Producte", "Producto", "Product")), ("q", L("Quocient", "Cociente", "Quotient")), ("pp", L("Potència de potència", "Potencia de potencia", "Power of a power"))], "p")}</div>\n'
  + f'  <div class="wrow" style="margin-top:8px"><label>{L("Base", "Base", "Base")} {fin("a", "b", "-2", "3", "text")}</label>{nin("m", "Exponent", "Exponente", "Exponent", "3", "s", "numeric")}<span data-p="m q pp">{nin("n", "2n exponent", "2.º exponente", "2nd exponent", "2", "s", "numeric")}</span></div>\n'
  + '  ' + quick([('p;-2;3;3', '(−2/3)³'), ('p;2;3;4', '(2/3)⁴'), ('p;-1;2;4', '(−1/2)⁴'), ('p;5;7;0', '(5/7)⁰'), ('p;-3;1;4', '(−3)⁴'), ('m;3;5;2;3', '(3/5)²·(3/5)³'), ('q;3;5;7;4', '(3/5)⁷:(3/5)⁴'), ('pp;3;5;2;3', '[(3/5)²]³')]) + '\n')
s9 += level(1, 1,
  prob(L(r"Calcula: a) \((-5)^3\) &nbsp; b) \(-5^2\) &nbsp; c) \((-1)^{20}\) &nbsp; d) \(\left(\frac{3}{4}\right)^3\) &nbsp; e) \(\left(-\frac{2}{5}\right)^2\) &nbsp; f) \(\left(\frac{7}{9}\right)^0\)", r"Calcula: a) \((-5)^3\) &nbsp; b) \(-5^2\) &nbsp; c) \((-1)^{20}\) &nbsp; d) \(\left(\frac{3}{4}\right)^3\) &nbsp; e) \(\left(-\frac{2}{5}\right)^2\) &nbsp; f) \(\left(\frac{7}{9}\right)^0\)", r"Work out: a) \((-5)^3\) &nbsp; b) \(-5^2\) &nbsp; c) \((-1)^{20}\) &nbsp; d) \(\left(\frac{3}{4}\right)^3\) &nbsp; e) \(\left(-\frac{2}{5}\right)^2\) &nbsp; f) \(\left(\frac{7}{9}\right)^0\)"),
       r'\[\text{a) }\boxed{-125}\qquad\text{b) }\boxed{-25}\qquad\text{c) }\boxed{1}\qquad\text{d) }\boxed{\frac{27}{64}}\qquad\text{e) }\boxed{\frac{4}{25}}\qquad\text{f) }\boxed{1}\]'))
chk('(-5)^3', -125); chk('-5^2', -25); chk('(-1)^20', 1); ck(pw(3, 4, 3), Fr(27, 64)); ck(pw(-2, 5, 2), Fr(4, 25))
s9 += level(2, 2,
  prob(L(r"Calcula: \(\ (-2)^3+3^2-(-1)^5\ \) i \(\ \left(-\frac{1}{2}\right)^3+\left(\frac{1}{2}\right)^2\).", r"Calcula: \(\ (-2)^3+3^2-(-1)^5\ \) y \(\ \left(-\frac{1}{2}\right)^3+\left(\frac{1}{2}\right)^2\).", r"Work out: \(\ (-2)^3+3^2-(-1)^5\ \) and \(\ \left(-\frac{1}{2}\right)^3+\left(\frac{1}{2}\right)^2\)."),
       r'\[-8+9-(-1)=-8+9+1=\boxed{2}\qquad -\frac{1}{8}+\frac{1}{4}=-\frac{1}{8}+\frac{2}{8}=\boxed{\frac{1}{8}}\]'))
chk('(-2)^3+3^2-(-1)^5', 2); ck(pw(-1, 2, 3) + pw(1, 2, 2), Fr(1, 8))
s9 += level(3, 3,
  prob(L(r"Una pilota es deixa caure des de 8 m i, cada vegada que bota, puja \(\frac{3}{4}\) de l'altura anterior. A quina altura arriba després del tercer bot?", r"Una pelota se deja caer desde 8 m y, cada vez que bota, sube \(\frac{3}{4}\) de la altura anterior. ¿A qué altura llega después del tercer bote?", r"A ball is dropped from 8 m and each bounce reaches \(\frac{3}{4}\) of the previous height. How high does it go after the third bounce?"),
       r'\[8\cdot\left(\frac{3}{4}\right)^3=8\cdot\frac{27}{64}=\frac{216}{64}=\boxed{\frac{27}{8}\ \text{m}=3{,}375\ \text{m}}\]'))
ck(8 * pw(3, 4, 3), Fr(27, 8))
s9 += practice([
  ('★', L(r"a) \((-4)^2\) &nbsp; b) \(-4^2\) &nbsp; c) \((-3)^3\) &nbsp; d) \(\left(\frac{1}{2}\right)^5\) &nbsp; e) \(\left(-\frac{3}{2}\right)^2\)", r"a) \((-4)^2\) &nbsp; b) \(-4^2\) &nbsp; c) \((-3)^3\) &nbsp; d) \(\left(\frac{1}{2}\right)^5\) &nbsp; e) \(\left(-\frac{3}{2}\right)^2\)", r"a) \((-4)^2\) &nbsp; b) \(-4^2\) &nbsp; c) \((-3)^3\) &nbsp; d) \(\left(\frac{1}{2}\right)^5\) &nbsp; e) \(\left(-\frac{3}{2}\right)^2\)")),
  ('★★', L(r"f) Signe, sense calcular: \((-7)^{12}\), \((-3)^{15}\), \(-5^4\), \(\left(-\frac{2}{9}\right)^{7}\). &nbsp; g) \(\ 2^4-(-2)^4+(-2)^3\)", r"f) Signo, sin calcular: \((-7)^{12}\), \((-3)^{15}\), \(-5^4\), \(\left(-\frac{2}{9}\right)^{7}\). &nbsp; g) \(\ 2^4-(-2)^4+(-2)^3\)", r"f) Sign, without working out: \((-7)^{12}\), \((-3)^{15}\), \(-5^4\), \(\left(-\frac{2}{9}\right)^{7}\). &nbsp; g) \(\ 2^4-(-2)^4+(-2)^3\)"))],
  P(r"a) \(16\) &nbsp; b) \(-16\) &nbsp; c) \(-27\) &nbsp; d) \(\frac{1}{32}\) &nbsp; e) \(\frac{9}{4}\) &nbsp; f) \(+\), \(-\), \(-\), \(-\) &nbsp; g) \(16-16-8=-8\)", r"a) \(16\) &nbsp; b) \(-16\) &nbsp; c) \(-27\) &nbsp; d) \(\frac{1}{32}\) &nbsp; e) \(\frac{9}{4}\) &nbsp; f) \(+\), \(-\), \(-\), \(-\) &nbsp; g) \(16-16-8=-8\)", r"a) \(16\) &nbsp; b) \(-16\) &nbsp; c) \(-27\) &nbsp; d) \(\frac{1}{32}\) &nbsp; e) \(\frac{9}{4}\) &nbsp; f) \(+\), \(-\), \(-\), \(-\) &nbsp; g) \(16-16-8=-8\)"))
chk('(-4)^2', 16); chk('-4^2', -16); chk('(-3)^3', -27); ck(pw(1, 2, 5), Fr(1, 32)); ck(pw(-3, 2, 2), Fr(9, 4)); chk('2^4-(-2)^4+(-2)^3', -8)

# ============================================================ 1.10 Propietats de les potències
s10 = box('prop', L('Propietats de les potències', 'Propiedades de las potencias', 'Laws of powers'),
  P(r"Valen per a qualsevol base \(a\), \(b\) (entera o fraccionària, diferent de 0) i exponents naturals \(m\), \(n\):",
    r"Valen para cualquier base \(a\), \(b\) (entera o fraccionaria, distinta de 0) y exponentes naturales \(m\), \(n\):",
    r"They hold for any base \(a\), \(b\) (integer or fraction, not 0) and natural exponents \(m\), \(n\):")
  + table([L('Propietat', 'Propiedad', 'Law'), L('Regla', 'Regla', 'Rule'), L('Amb enters', 'Con enteros', 'With integers'), L('Amb fraccions', 'Con fracciones', 'With fractions')],
        [[L('Producte de potències amb la <strong>mateixa base</strong>: se <strong>sumen</strong> els exponents', 'Producto de potencias con la <strong>misma base</strong>: se <strong>suman</strong> los exponentes', 'Product, <strong>same base</strong>: <strong>add</strong> the exponents'), r'\(a^m\cdot a^n=a^{m+n}\)', r'\((-2)^3\cdot(-2)^5=(-2)^8\)', r'\(\left(\frac{3}{5}\right)^2\cdot\left(\frac{3}{5}\right)^3=\left(\frac{3}{5}\right)^5\)'],
         [L('Quocient de potències amb la <strong>mateixa base</strong>: se <strong>resten</strong> els exponents', 'Cociente de potencias con la <strong>misma base</strong>: se <strong>restan</strong> los exponentes', 'Quotient, <strong>same base</strong>: <strong>subtract</strong> the exponents'), r'\(a^m:a^n=a^{m-n}\)', r'\(7^9:7^6=7^3\)', r'\(\left(\frac{3}{5}\right)^7:\left(\frac{3}{5}\right)^4=\left(\frac{3}{5}\right)^3\)'],
         [L("Potència d'una potència: se <strong>multipliquen</strong> els exponents", 'Potencia de una potencia: se <strong>multiplican</strong> los exponentes', 'Power of a power: <strong>multiply</strong> the exponents'), r'\(\left(a^m\right)^n=a^{m\cdot n}\)', r'\(\left[(-3)^2\right]^4=(-3)^8\)', r'\(\left[\left(\frac{1}{2}\right)^2\right]^3=\left(\frac{1}{2}\right)^6\)'],
         [L('Producte amb el <strong>mateix exponent</strong>: es multipliquen les bases', 'Producto con el <strong>mismo exponente</strong>: se multiplican las bases', 'Product, <strong>same exponent</strong>: multiply the bases'), r'\(a^n\cdot b^n=(a\cdot b)^n\)', r'\(2^5\cdot5^5=10^5\)', r'\(\left(\frac{3}{4}\right)^3\cdot\left(\frac{2}{9}\right)^3=\left(\frac{1}{6}\right)^3\)'],
         [L('Quocient amb el <strong>mateix exponent</strong>: es divideixen les bases', 'Cociente con el <strong>mismo exponente</strong>: se dividen las bases', 'Quotient, <strong>same exponent</strong>: divide the bases'), r'\(a^n:b^n=(a:b)^n\)', r'\((-12)^4:3^4=(-4)^4\)', r'\(\left(\frac{4}{5}\right)^2:\left(\frac{2}{5}\right)^2=2^2\)']], 'data')
  + note(r"Les propietats només valen per a <strong>productes i quocients</strong>. Amb sumes i restes no: \(\ 2^3+2^2=8+4=12\neq2^5\) &nbsp; i &nbsp; \((3+4)^2=49\neq3^2+4^2=25\).",
         r"Las propiedades solo valen para <strong>productos y cocientes</strong>. Con sumas y restas no: \(\ 2^3+2^2=8+4=12\neq2^5\) &nbsp; y &nbsp; \((3+4)^2=49\neq3^2+4^2=25\).",
         r"These laws only work for <strong>products and quotients</strong>. Not for sums or differences: \(\ 2^3+2^2=8+4=12\neq2^5\) &nbsp; and &nbsp; \((3+4)^2=49\neq3^2+4^2=25\).", '⚠️'))
chk('(-2)^3·(-2)^5', 256); chk('(-12)^4:3^4', 256); ck(pw(3, 4, 3) * pw(2, 9, 3), pw(1, 6, 3)); ck(pw(4, 5, 2) / pw(2, 5, 2), 4)
s10 += box('def', L('Per què funcionen?', '¿Por qué funcionan?', 'Why do they work?'),
  P(r"N'hi ha prou amb escriure els factors: \(\ 2^3\cdot2^2=(2\cdot2\cdot2)\cdot(2\cdot2)=2^5\) &nbsp; i &nbsp; \(\ \dfrac{5^4}{5^2}=\dfrac{5\cdot5\cdot\cancel{5}\cdot\cancel{5}}{\cancel{5}\cdot\cancel{5}}=5^2\). Si els dos exponents són iguals, el quocient és 1: \(a^n:a^n=a^0=1\).",
    r"Basta con escribir los factores: \(\ 2^3\cdot2^2=(2\cdot2\cdot2)\cdot(2\cdot2)=2^5\) &nbsp; y &nbsp; \(\ \dfrac{5^4}{5^2}=\dfrac{5\cdot5\cdot\cancel{5}\cdot\cancel{5}}{\cancel{5}\cdot\cancel{5}}=5^2\). Si los dos exponentes son iguales, el cociente es 1: \(a^n:a^n=a^0=1\).",
    r"Just write out the factors: \(\ 2^3\cdot2^2=(2\cdot2\cdot2)\cdot(2\cdot2)=2^5\) &nbsp; and &nbsp; \(\ \dfrac{5^4}{5^2}=\dfrac{5\cdot5\cdot\cancel{5}\cdot\cancel{5}}{\cancel{5}\cdot\cancel{5}}=5^2\). If both exponents are equal, the quotient is 1: \(a^n:a^n=a^0=1\).")
  + note(r"Truc: si la base és negativa i l'exponent és <strong>parell</strong>, podem llevar el signe: \((-3)^4=3^4\). Així podem ajuntar \((-3)^4\cdot3^2=3^4\cdot3^2=3^6\).",
         r"Truco: si la base es negativa y el exponente es <strong>par</strong>, podemos quitar el signo: \((-3)^4=3^4\). Así podemos juntar \((-3)^4\cdot3^2=3^4\cdot3^2=3^6\).",
         r"Tip: if the base is negative and the exponent is <strong>even</strong>, the sign can go: \((-3)^4=3^4\). So \((-3)^4\cdot3^2=3^4\cdot3^2=3^6\)."))
chk('(-3)^4·3^2', 729)
s10 += drill('pow', 'Entrena: potències de fraccions i propietats', 'Entrena: potencias de fracciones y propiedades', 'Train: powers of fractions and their laws')
s10 += hier(["(2/3)^5·(2/3)^2:(2/3)^4", "(-1/2)^3·(-1/2)^2", "(3/4)^6:(3/4)^4", "(5/6)^3·(6/5)^3", "2^3·2^2:2^4", "(1/2)^2+(1/2)^3"])
